module palindrome_count #(parameter N=4) (\n    input clk,\n    input rst_n,\n    input start,\n    input [N-1:0] S,\n    output reg [31:0] result,\n    output reg done\n);\n\n    // Constants\n    localparam [31:0] MOD = 1000000007;\n    localparam IDLE        = 3'd0;\n    localparam SETUP       = 3'd1;\n    localparam SCAN        = 3'd2;\n    localparam UPDATE_COUNT = 3'd3;\n    localparam FINISH      = 3'd4;\n\n    reg [2:0] state;\n    reg [N-1:0] first_half;\n    reg [4:0] pos;\n    reg [N-1:0] matched;\n    reg [31:0] count;\n    reg [N-1:0] max_first_half;\n\n    wire palindrome_char;\n    assign palindrome_char = (pos < N) ? first_half[pos] : first_half[2*N-1 - pos];\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            result <= 32'd0;\n            done <= 1'b0;\n            count <= 32'd0;\n            first_half <= {N{1'b0}};\n            pos <= 5'd0;\n            matched <= {N{1'b0}};\n            max_first_half <= {N{1'b1}};\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    count <= 32'd0;\n                    if (start) begin\n                        state <= SETUP;\n                        first_half <= {N{1'b0}};\n                    end\n                end\n\n                SETUP: begin\n                    pos <= 5'd0;\n                    matched <= {N{1'b0}};\n                    state <= SCAN;\n                end\n\n                SCAN: begin\n                    if (matched < N && palindrome_char == S[matched]) begin\n                        matched <= matched + 1;\n                    end\n                    pos <= pos + 1;\n                    if (pos == 2*N - 1) begin\n                        state <= UPDATE_COUNT;\n                    end\n                end\n\n                UPDATE_COUNT: begin\n                    if (matched == N) begin\n                        count <= (count + 1) % MOD;\n                    end\n                    if (first_half == max_first_half) begin\n                        state <= FINISH;\n                    end else begin\n                        first_half <= first_half + 1;\n                        state <= SETUP;\n                    end\n                end\n\n                FINISH: begin\n                    result <= count;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule